	"settings.spendSavedCodex.desc":
		"自动消耗已保存的 Codex 限流重置：当回合卡住且没有其他账号可接管时，恢复被耗尽的 5 小时或每周窗口封锁的账号，并挽救即将过期的额度。unset 在首次消耗前询问，yes 直接消耗不提示，no 禁用两项检查。",
	"settings.onlyAutoRedeem.desc":
		"仅当自然解锁——耗尽的 5 小时/每周窗口中最新的重置——至少还有这么多分钟时才自动兑换（不要为省下短暂等待而消耗稀缺额度）。调高（如 360）可忽略仅 5 小时窗口的封锁。",
	"settings.neverAutoSpend.desc":
		"低于此数量的已保存重置时绝不自动消耗（0 = 最后一条额度也可能被自动消耗）。即将过期的额度除外——保留的额度过期即一无所有。",
	"settings.spendSavedCodex.desc2":
		"当已保存的 Codex 重置将在此小时数内过期、且任一聊天窗口（5 小时或每周）有可恢复的有效用量时自动消耗它（0 禁用过期挽救）。",
	"settings.enableExaWebSearch": "启用 Exa 网络搜索提供商",
