	"Auto (only for models without vision)": "自动（仅限无视觉模型）",
	"Auto QA": "自动质量检测",
	"Auto QA Push Endpoint": "自动质量检测推送端点",
	"Auto Resume": "自动恢复",
	"Auto Thinking Ceiling": "自动思考上限",
